/**
 * Nearest-city lookup for the map cursor readout.
 *
 * The bundled list (src/assets/geodata/cities.json, generated by
 * scripts/generate-cities.mjs from GeoNames) holds ~2,000 cities with
 * population > 300k as [name, lat, lon, population, countryCode]. A 10°
 * lat/lon bucket index makes each lookup touch a few dozen rows instead of
 * all of them, so calling it on every mousemove is fine.
 */
import cities from '../assets/geodata/cities.json';

const BUCKET_DEG = 10;
const R_KM = 6371;
const toRad = (d) => (d * Math.PI) / 180;

function haversineKm(lat1, lon1, lat2, lon2) {
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * R_KM * Math.asin(Math.min(1, Math.sqrt(a)));
}

const normLon = (lon) => ((((lon + 180) % 360) + 360) % 360) - 180;
const bucketKey = (lat, lon) => `${Math.floor(lat / BUCKET_DEG)}:${Math.floor(normLon(lon) / BUCKET_DEG)}`;

/** Build the bucket index once per city list. */
export function buildCityIndex(list = cities) {
  const index = new Map();
  list.forEach((row, i) => {
    const key = bucketKey(row[1], row[2]);
    let arr = index.get(key);
    if (!arr) index.set(key, (arr = []));
    arr.push(i);
  });
  return { list, index };
}

let defaultIndex = null;

/**
 * Nearest city to (lat, lon) within `maxKm`.
 * → { name, lat, lon, population, country, km } or null.
 */
export function nearestCity(lat, lon, maxKm = 100, idx = null) {
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  if (!idx) idx = defaultIndex || (defaultIndex = buildCityIndex());
  const { list, index } = idx;
  const nl = normLon(lon);
  const bLat = Math.floor(lat / BUCKET_DEG);
  const bLon = Math.floor(nl / BUCKET_DEG);
  // 100 km is < 1° of latitude, so the neighbouring 10° buckets always cover
  // the search radius (longitude buckets shrink toward the poles, which only
  // widens the covered area).
  let best = null;
  let bestKm = maxKm;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      let bx = bLon + dx;
      if (bx < -18) bx += 36;
      if (bx > 17) bx -= 36;
      const bucket = index.get(`${bLat + dy}:${bx}`);
      if (!bucket) continue;
      for (const i of bucket) {
        const row = list[i];
        const km = haversineKm(lat, lon, row[1], row[2]);
        if (km < bestKm) {
          bestKm = km;
          best = row;
        }
      }
    }
  }
  if (!best) return null;
  return { name: best[0], lat: best[1], lon: best[2], population: best[3], country: best[4], km: bestKm };
}

/** "1.2M" / "850k" style population. */
export function formatPopulation(pop) {
  if (!Number.isFinite(pop)) return '';
  if (pop >= 1e6) return `${(pop / 1e6).toFixed(pop >= 1e7 ? 0 : 1)}M`;
  return `${Math.round(pop / 1e3)}k`;
}

export const CITY_COUNT = cities.length;

export default nearestCity;
